using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Input;
namespace StarlightSyndicateDemo;
public sealed partial class DemoGame
{
 void InformationTestPointer(Vector2 at,ButtonState left=ButtonState.Released){mouse=at;var m=new MouseState((int)at.X,(int)at.Y,0,left,ButtonState.Released,ButtonState.Released,ButtonState.Released,ButtonState.Released);if(!InformationInput(m))DesktopInput(m,new KeyboardState());oldMouse=m;}
 void InformationTestDrag(Vector2 from,Vector2 to){InformationTestPointer(from);InformationTestPointer(from,ButtonState.Pressed);InformationTestPointer(to,ButtonState.Pressed);InformationTestPointer(to);}
 int informationUiChecks;string informationTestKey="";DesktopWindow? informationTestWindow;
 void RunInformationUiChecks(int stage){if(stage>19)return;void Check(bool ok,string label){UiCheck(ok,label);informationUiChecks++;}DesktopWindow First()=>informationTestWindow!;void Click(DesktopWindow w,string tip)=>TestClick(ui.Hits.Last(h=>h.Owner==w.Owner&&h.Tip==tip).Rect.Center.ToVector2());
 switch(stage){
 case 0:var windows=desktop.Where(w=>w.Kind==ViewMode.Information).ToArray();Check(windows.Length==2&&windows[0].Owner!=windows[1].Owner,"Distinct object windows have independent input ownership");informationTestKey=windows[0].InfoKey;informationTestWindow=windows[0];Check(windows[0].InfoTab=="Description"&&windows[1].InfoTab=="Attributes","Tabs are independent per object");Click(windows[0],"Info tab / Fitting");Check(windows[0].InfoTab=="Fitting"&&windows[1].InfoTab=="Attributes","Clicking one tab leaves the other object unchanged");break;
 case 1:var a=First();int x=a.X;TestDrag(new(a.X+120,a.Y+12),new(a.X+100,a.Y+22));Check(a.X==x-20,"Individual info title drag moves its own window");break;
 case 2:var resize=First();int width=resize.Width;TestDrag(new(resize.Bounds.Right-5,resize.Bounds.Bottom-5),new(resize.Bounds.Right+5,resize.Bounds.Bottom+5));Check(resize.Width==width+10,"Individual info grip resizes its own window");SaveDesktop();Check(File.Exists(LayoutPath),"Information window geometry persists");break;
 case 3:var history=First();NavigateInformation(history,"system/aster");Check(history.InfoKey=="system/aster"&&history.InfoHistory.Count==2,"Related-object navigation records window-local history");Check(desktop.Count(w=>w.Kind==ViewMode.Information)==2,"Navigating a link reuses only its originating window");history.InfoTab="Orbital Bodies";break;
 case 4:var system=desktop.First(w=>w.InfoKey=="system/aster");var link=ui.Hits.First(h=>h.Owner==system.Owner&&h.Tip.StartsWith("Info link / celestial/"));TestClick(link.Rect.Center.ToVector2());Check(system.InfoKey.StartsWith("celestial/"),"Orbital body link opens real celestial information");break;
 case 5:var celestial=First();Click(celestial,"Info back");Check(celestial.InfoKey=="system/aster","History back returns to solar-system record");Click(celestial,"Info back");Check(celestial.InfoKey==informationTestKey,"History back returns to original module");break;
 case 6:var module=First();ShowInformation(module.InfoKey);Check(desktop.Count(w=>w.Kind==ViewMode.Information)==2,"Repeated Show Info focuses existing object window");ShowInformation(module.InfoKey,true);Check(desktop.Count(w=>w.Kind==ViewMode.Information)==3,"Explicit duplicate supports same-type comparison");OpenEncyclopedia("system/aster");break;
 case 7:Check(encyclopediaEntries.Count>InformationCatalog.All.Length,"Encyclopedia includes live objects as well as every static type");Check(encyclopediaExpanded.Contains("Universe")&&encyclopediaSelected=="system/aster","Category tree expands to selected system");encyclopediaQuery="Vesperite";Check(EncyclopediaResults().Any(e=>e.Id=="ore"),"Global encyclopedia search includes materials");encyclopediaQuery="";encyclopediaGroup="Universe / Regions";Check(EncyclopediaResults().All(e=>e.Kind=="Region"),"Region category filters real universe records");encyclopediaGroup="Universe / Solar systems";break;
 case 8:var db=desktop.First(w=>w.Kind==ViewMode.Catalog);Click(db,"Encyclopedia open selected info");Check(desktop.Last().Kind==ViewMode.Information&&desktop.Last().InfoKey=="system/aster","Database Show Info opens a separate object window");ToggleEncyclopediaFavorite("system/aster");Check(encyclopediaFavorites.Contains("system/aster")&&File.Exists(EncyclopediaPreferencesPath),"Quickbar favorite saves to user preferences");break;
 case 9:var info=desktop.Last();InformationHistory(info,-1);Check(info.InfoKey=="system/aster"&&info.InfoHistory.Count==1&&First().InfoKey==informationTestKey,"History stays independent after database navigation");var entry=ResolveInformation(informationTestKey)!;OpenInformationComparison(entry);Check(desktop.Last().InfoKey=="comparison"&&informationCompare.Count>1,"Variations open an actual multi-item comparison");break;
 case 10:var comp=desktop.Last();Click(comp,"Compare differences");Check(infoDifferences,"Comparison difference filter works");ShowInformation("pilot/player");Check(ResolveInformation("pilot/player")!.Tabs["Attributes"].Any(r=>r.Label=="Credits"),"Pilot window exposes current character information");break;
 case 11:var pilot=desktop.Last();TestClick(new(pilot.Bounds.Right-40,pilot.Y+12));Check(pilot.Minimized,"Information window minimizes independently");ShowInformation("pilot/player");Check(!pilot.Minimized&&desktop.Last()==pilot,"Show Info restores minimized object window");TestClick(new(pilot.Bounds.Right-15,pilot.Y+12));Check(!desktop.Contains(pilot),"Closing an object window preserves the others");break;
 case 12:var item=ItemCatalog.All.First(i=>i.Id=="ore");MarketShowInfo(Array.IndexOf(ItemCatalog.All,item));Check(desktop.Last().InfoKey=="item/ore"&&desktop.Last().Kind==ViewMode.Information,"Market info command opens item window instead of registry");ShowInformation("ship/player");Check(ResolveInformation("ship/player")!.Tabs.ContainsKey("Equipment"),"Live ship information lists actual installed equipment");break;
 case 13:var target=world.Targets.FirstOrDefault();if(target!=null){ShowObjectInfo(target.Id);Check(desktop.Last().InfoKey.StartsWith("target/")||desktop.Last().InfoKey.StartsWith("celestial/"),"Space objects use the same information system");}ShowInformation("system/umbra");var route=InformationRows(ResolveInformation("system/umbra")!,"Route");Check(route.Any(r=>r.Link=="system/rook")&&route.Any(r=>r.Link=="system/umbra"),"Route tab calculates real gate path from current location");world.Player.ApplyFleetHull(FleetCatalog.Source("Tristan"));world.Credits=100000;ShowInformation("ship/player");desktop.Last().InfoTab="Traits";break;
 case 14:var training=desktop.Last();int skill=world.Player.ActiveHullTraits.First(t=>t.Skill!=0).Skill;int oldLevel=world.Player.HullProficiency.GetValueOrDefault(skill,1);Click(training,"Info train / "+skill);Check(world.Player.HullProficiency[skill]==oldLevel+1,"Info Traits training button preserves actual proficiency mechanics");break;
 case 15:Check(ResolveInformation("ship/player")!.Tabs["Attributes"].Any(r=>r.Label=="Shield Capacity"||r.Label.Contains("Shield")),"Live ship attributes remain available after training");desktop.Last().InfoTab="Model";break;
 case 16:var model=desktop.Last();float yaw=renderer.Yaw,previewYaw=model.InfoModelYaw;Click(model,"Info model rotate right");Check(model.InfoModelYaw>previewYaw&&renderer.Yaw==yaw,"3D info model rotates independently of world camera");var viewport=informationPreviewRects[model.Owner];float pitch=model.InfoModelPitch;InformationTestDrag(viewport.Center.ToVector2(),viewport.Center.ToVector2()+new Vector2(25,16));Check(model.InfoModelPitch!=pitch,"Dragging model rotates only its own info preview");ShowItemInfo(FleetCatalog.Source("Kestrel").Id);desktop.Last().InfoTab="Model";break;
 case 17:Check(desktop.Where(w=>w.Kind==ViewMode.Information&&w.InfoTab=="Model").All(w=>informationPreviews.ContainsKey(w.InstanceId)),"Several hull info windows have separate native 3D previews");var lodWindow=desktop.Last();Click(lodWindow,"Info model LOD");Check(lodWindow.InfoModelLod==1,"Info model LOD control changes its own preview");break;
 case 19:Console.WriteLine($"{informationUiChecks} information and encyclopedia UI checks passed.");break;
 }}
}
